import 'server-only'

import { readFile, mkdir, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { cacheTag } from 'next/cache'

type Post = {
  id: string
  title: string
  content: string
}

const postsFile = join(process.cwd(), 'data', 'posts.json')

async function readPosts(): Promise<Post[]> {
  try {
    return JSON.parse(await readFile(postsFile, 'utf8')) as Post[]
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []
    throw error
  }
}

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return readPosts()
}

export async function addPost(title: string, content: string): Promise<void> {
  const posts = await readPosts()
  posts.unshift({ id: crypto.randomUUID(), title, content })
  await mkdir(join(process.cwd(), 'data'), { recursive: true })
  await writeFile(postsFile, JSON.stringify(posts, null, 2))
}

